// === Tab: imitate ===
function imitate(points, k) {
	let result = [];
	points.forEach(
		p => {
			let p2 = {
				angle: p.angle,
				radius: p.radius + 15 * sin(k) * noise(111+cos(p.angle+k), 111+sin(p.angle+k), k)
			};
			result.push(p2);
		}
	);

	return result;
}

// === Tab: mySketch ===
let init_p;

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(212);
	loop();

	init_p = [];
	for (let angle = 0; angle < TAU; angle += TAU/100) {
		let p = {
			angle,
			radius: 10
		};
		init_p.push(p);
	}
}

function draw_p(points) {
	noFill()
	beginShape();
	points.forEach(p => {
		let x = width / 2 + p.radius * cos(p.angle);
		let y = height / 2 + p.radius * sin(p.angle);
		vertex(x, y)
	});
	endShape(CLOSE);
}

function run_imitate(num, points) {
	var result = points;
	for (let i = 0; i < num; i++) {
		result = imitate(result, i*0.1  /*frameCount*0.01*/)
	}
	return result;
}


function draw() {
	background(212);

	for(let i=4; i<25; i++){		
		draw_p(run_imitate(i, init_p));
	}

	// noLoop() removed for animation
}

function mousePressed() {
	redraw(); // setup();
}
